import {visualClip} from './studio-core.js';import {reviewClip} from './review-core.js';import {drawMotionScene} from './motion-design.js';import {transitionMix} from './transition-core.js';
const layers=new WeakMap();
export function resetFrameContext(ctx){ctx.setTransform(1,0,0,1,0,0);ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';ctx.filter='none';ctx.shadowBlur=0;ctx.shadowOffsetX=ctx.shadowOffsetY=0;}
function layerFor(canvas){let l=layers.get(canvas);if(!l){l={current:document.createElement('canvas'),previous:document.createElement('canvas')};layers.set(canvas,l)}for(const c of Object.values(l))if(c.width!==canvas.width||c.height!==canvas.height){c.width=canvas.width;c.height=canvas.height}return l}
export function paintSceneLayer(target,clip,offset,source,{aspect,preset}){const ctx=target.getContext('2d'),w=target.width,h=target.height;resetFrameContext(ctx);ctx.fillStyle='#08080a';ctx.fillRect(0,0,w,h);if(!source)return;const v=visualClip(clip),r=reviewClip(clip),duration=(clip.end-clip.start)/(clip.speed||1),p=Math.max(0,Math.min(1,offset/duration)),motion=r.motion==='push'?1+p*.06:r.motion==='pull'?1.06-p*.06:1;ctx.save();ctx.filter=`brightness(${v.brightness}) contrast(${v.contrast}) saturate(${v.saturation})`;ctx.translate(w/2,h/2);ctx.rotate(v.rotation*Math.PI/180);ctx.scale((v.flip?-1:1)*v.zoom*motion,v.zoom*motion);ctx.translate(-w/2,-h/2);const iw=source.videoWidth||source.naturalWidth||source.width,ih=source.videoHeight||source.naturalHeight||source.height;if(iw&&ih){const zoom=source.tagName==='IMG'&&preset==='cinematic'?1+offset*.008:1,scale=Math.max(w/iw,h/ih)*zoom;ctx.drawImage(source,(w-iw*scale)/2,(h-ih*scale)/2,iw*scale,ih*scale)}ctx.restore();if(clip.motionDesign?.enabled)drawMotionScene(ctx,target,clip,offset,source)}
export function wipeEdge(progress,width,feather){return width+feather-(width+2*feather)*Math.max(0,Math.min(1,progress))}
export function paintSceneBackground(ctx,canvas,{clip,offset,source,previous,previousClip,duration,state}){const l=layerFor(canvas);paintSceneLayer(l.current,clip,offset,source,state);resetFrameContext(ctx);ctx.fillStyle='#08080a';ctx.fillRect(0,0,canvas.width,canvas.height);if(!previous||!previousClip||!duration||offset>=duration){ctx.drawImage(l.current,0,0);return}const previousOffset=(previousClip.end-previousClip.start)/(previousClip.speed||1)-duration+offset;paintSceneLayer(l.previous,previousClip,Math.max(0,previousOffset),previous,state);ctx.drawImage(l.previous,0,0);const progress=transitionMix(offset,duration);if(clip.transition==='fade'){ctx.save();ctx.globalAlpha=progress;ctx.drawImage(l.current,0,0);ctx.restore();return}const mask=l.current.getContext('2d'),feather=Math.min(canvas.width,canvas.height)*.06,edge=wipeEdge(progress,canvas.width,feather),gradient=mask.createLinearGradient(edge-feather,0,edge+feather,0);gradient.addColorStop(0,'rgba(255,255,255,0)');gradient.addColorStop(1,'rgba(255,255,255,1)');mask.save();mask.globalCompositeOperation='destination-in';mask.fillStyle=gradient;mask.fillRect(0,0,canvas.width,canvas.height);mask.restore();ctx.drawImage(l.current,0,0)}
